from pathlib import Path

p = Path("src/components/TracksPlayer.jsx")
s = p.read_text()

# Remove temporary test text.
s = s.replace('<div className="nyxtryp-auto-test">ПРИВЕТ</div>', '')
s = s.replace('ПРИВЕТ', '')

# Replace the existing meter with the actual SVG geometry of reference #3.
start_marker = '          {!isMobile && (\n            <div className="tracks-mc-vu">'
end_marker = '          <div className="tracks-controls">'
start = s.find(start_marker)
end = s.find(end_marker, start)
if start < 0 or end < 0:
    raise SystemExit("VU markup boundaries not found")

new_block = '''          {!isMobile && (\n            <div className="tracks-mc-vu">\n              {[['L', leftVU], ['R', rightVU]].map(([channel, value]) => {\n                const db = Math.max(-40, Math.min(10, value))\n                const normalized = (db + 40) / 50\n                const angle = 15 + normalized * 60\n\n                return (\n                  <div className="tracks-mc-meter" key={channel}>\n                    <div className="tracks-mc-window">\n                      <svg className="tracks-mc-gauge" viewBox="0 0 1080 633" preserveAspectRatio="xMidYMid meet" aria-label={`${channel} analog VU meter`}>\n                        <defs>\n                          <linearGradient id={`vu-bg-${channel}`} x1="0" y1="0" x2="0" y2="1">\n                            <stop offset="0" stopColor="#fff1b0" />\n                            <stop offset="1" stopColor="#c9b86d" />\n                          </linearGradient>\n                          <filter id={`vu-shadow-${channel}`} x="-30%" y="-30%" width="160%" height="160%">\n                            <feGaussianBlur stdDeviation="8" />\n                          </filter>\n                        </defs>\n\n                        <rect x="0" y="0" width="1077" height="633" fill={`url(#vu-bg-${channel})`} />\n                        <path d="m 537.18074,590.23438 a 150.76556,150.76556 0 0 0 -107.3086,45.05078 l 214.73829,0 A 150.76556,150.76556 0 0 0 537.18074,590.23438 Z" fill="#000" />\n\n                        <path d="m 126.01626,357.7731 c 161.49448,-60.14366 315.01211,-98.096 531.2366,-81.4418" fill="none" stroke="#111" strokeWidth="15" />\n                        <path d="m 657,277.24518 c 85.60879,8.87328 173.21481,25.29511 295.97922,75.9692" fill="none" stroke="#d71920" strokeWidth="15" />\n\n                        <g fill="none" stroke="#111" strokeWidth="8">\n                          <path d="m 210.72277,271.30126 34.37058,47.77511" />\n                          <path d="m 285.65064,249.6478 27.49646,52.24328" />\n                          <path d="m 365.73409,233.49363 18.56011,52.93069" />\n                          <path d="m 451.66054,221.12022 8.93635,53.96181" />\n                          <path d="m 544.1174,217.33945 -0.68741,53.96181" />\n                          <path d="m 620.76379,220.0891 -8.59264,53.2744" />\n                        </g>\n                        <g fill="none" stroke="#d71920" strokeWidth="8">\n                          <path d="m 669.22631,226.96322 -14.43565,56.36775" />\n                          <path d="m 777.83734,243.8048 -24.40311,48.80622" />\n                          <path d="m 864.4512,318.73266 34.37058,-43.65063" />\n                        </g>\n\n                        <g fill="#111" fontFamily="Arial, sans-serif" fontSize="40" fontWeight="700" textAnchor="middle">\n                          <text x="160" y="244">-40</text>\n                          <text x="252" y="222">-30</text>\n                          <text x="349" y="210">-20</text>\n                          <text x="440" y="202">-10</text>\n                          <text x="531" y="195">0</text>\n                          <text x="663" y="203">+10</text>\n                        </g>\n                        <text x="540" y="394" textAnchor="middle" fontFamily="Arial, sans-serif" fontSize="58" fontWeight="900" fill="#111">VU</text>\n                        <text x="540" y="430" textAnchor="middle" fontFamily="Arial, sans-serif" fontSize="22" fontWeight="700" fill="#111">{channel}</text>\n\n                        <path\n                          d="M 184.04706,291.70923 L 537.57412,730.481"\n                          fill="none"\n                          stroke="#111"\n                          strokeWidth="6.7"\n                          strokeLinecap="round"\n                          filter={`url(#vu-shadow-${channel})`}\n                          opacity=".35"\n                        />\n                        <g transform={`rotate(${angle} 537.57412 730.481)`}>\n                          <path\n                            d="M 184.04706,291.70923 L 537.57412,730.481"\n                            fill="none"\n                            stroke="#111"\n                            strokeWidth="6.7"\n                            strokeLinecap="round"\n                          />\n                        </g>\n                        <circle cx="537.66882" cy="730.48907" r="14" fill="#fff" stroke="#111" strokeWidth="4" />\n                      </svg>\n                    </div>\n                  </div>\n                )\n              })}\n            </div>\n          )}\n\n'''
s = s[:start] + new_block + s[end:]

css_start = s.find('        .tracks-mc-vu {')
css_end = s.find('        @media (max-width: 600px) {', css_start)
if css_start < 0 or css_end < 0:
    raise SystemExit("VU CSS boundaries not found")

new_css = '''        .tracks-mc-vu {\n          display: flex;\n          width: 100%;\n          gap: 14px;\n          justify-content: center;\n          align-items: stretch;\n          padding: 2px 0 4px;\n        }\n\n        .tracks-mc-meter {\n          flex: 1 1 0;\n          min-width: 0;\n        }\n\n        .tracks-mc-window {\n          width: 100%;\n          overflow: hidden;\n          border-radius: 3px;\n          background: #02080c;\n          border: 1px solid rgba(190,214,228,.42);\n          box-shadow: inset 0 0 0 1px rgba(0,0,0,.95), 0 5px 15px rgba(0,0,0,.28);\n        }\n\n        .tracks-mc-gauge {\n          width: 100%;\n          height: auto;\n          display: block;\n          aspect-ratio: 1080 / 633;\n        }\n\n'''
s = s[:css_start] + new_css + s[css_end:]
p.write_text(s)
print("NYXTRYP: installed actual reference #3 SVG geometry")
